-- Compatibility migration for databases where migration 009 was applied partially
-- or PostgREST has not refreshed its schema cache.
create table if not exists public."PHIEU_XUAT" (
  "ma_phieu_xuat" integer generated by default as identity primary key,
  "ma_phieu_code" varchar(80) not null unique,
  "ma_donhang" varchar not null references public."DON_HANG"("ma_donhang"),
  "ma_kho_xuat" integer not null references public."KHO"("ma_kho"),
  "trang_thai" varchar not null default 'NHAP' check ("trang_thai" in ('NHAP','DA_XAC_NHAN','DA_XUAT','HUY')),
  "nguoi_tao" varchar,
  "nguoi_xac_nhan" varchar,
  "ngay_tao" timestamptz not null default now(),
  "ngay_xac_nhan" timestamptz,
  "ghi_chu" text
);

create table if not exists public."CT_PHIEU_XUAT" (
  "ma_phieu_xuat" integer not null references public."PHIEU_XUAT"("ma_phieu_xuat") on delete cascade,
  "sku" varchar not null references public."SAN_PHAM"("sku"),
  "ma_kho_xuat" integer not null references public."KHO"("ma_kho"),
  "so_luong" integer not null check ("so_luong" > 0),
  "ten_sp_luc_xuat" varchar,
  "don_vi_luc_xuat" varchar,
  primary key ("ma_phieu_xuat", "sku", "ma_kho_xuat")
);

create or replace function public.create_dispatch_document(
  p_ma_donhang varchar,
  p_ma_kho_xuat integer,
  p_nguoi_tao varchar,
  p_ghi_chu text,
  p_lines jsonb
)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  order_row record;
  doc_id integer;
  doc_code varchar;
begin
  select * into order_row from public."DON_HANG" where "ma_donhang" = p_ma_donhang for update;
  if not found then raise exception using errcode = 'P0080', message = 'ORDER_NOT_FOUND'; end if;
  if order_row."trang_thai" in ('DA_XUAT_KHO', 'HOAN_THANH', 'HUY') then
    raise exception using errcode = 'P0081', message = 'ORDER_NOT_EDITABLE';
  end if;
  if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception using errcode = 'P0082', message = 'DISPATCH_HAS_NO_LINES';
  end if;
  doc_code := 'PX-' || p_ma_donhang || '-' || substr(md5(clock_timestamp()::text || random()::text), 1, 6);
  insert into public."PHIEU_XUAT"("ma_phieu_code", "ma_donhang", "ma_kho_xuat", "nguoi_tao", "ghi_chu")
    values (doc_code, p_ma_donhang, p_ma_kho_xuat, p_nguoi_tao, p_ghi_chu)
    returning "ma_phieu_xuat" into doc_id;
  insert into public."CT_PHIEU_XUAT"("ma_phieu_xuat", "sku", "ma_kho_xuat", "so_luong")
    select doc_id, item->>'sku', (item->>'warehouse_id')::integer, (item->>'quantity')::integer
    from jsonb_array_elements(p_lines) item;
  return jsonb_build_object('ma_phieu_xuat', doc_id, 'ma_phieu_code', doc_code, 'trang_thai', 'NHAP');
end; $$;

revoke all on function public.create_dispatch_document(varchar, integer, varchar, text, jsonb) from public, anon, authenticated;
grant execute on function public.create_dispatch_document(varchar, integer, varchar, text, jsonb) to service_role;

-- Force PostgREST to rebuild its RPC schema cache after applying this migration.
notify pgrst, 'reload schema';
